@ApplicationScoped
public class PriceChangeFilter extends CapturingFieldsFilterStrategy {
    public PriceChangeFilter() {
        super(Set.of("name", "price"));
    }
}

@Capturing(filter = PriceChangeFilter.class)
public void capture(CapturingEvent<SourceRecord, SourceRecord> event) {
    // only receives events where 'name' or 'price' are impacted
}

@Capturing(filter = PriceChangeFilter.class)
public void onBatch(CapturingEvents<BatchEvent> events) {
    // only receives batch events where at least one record impacts 'name' or 'price'
}

